 p=argparse.ArgumentParser();p.add_argument('--parent',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();a.output.mkdir(parents=True);r=json.loads((a.parent/'result.json').read_text());changes=dict(r['changed_sources'])
